import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Stethoscope, ArrowLeft, Mail, Lock, User, Phone, Eye, EyeOff } from 'lucide-react';
import { authService } from '../services/api';
import { Card, Button, Input, PageHeader } from '../components/UI';
import toast from 'react-hot-toast';

export default function SignUpPage() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [form, setForm] = useState({
    fullName: '',
    email: '',
    password: '',
    confirmPassword: '',
    phone: '',
    role: 'Patient',
  });
  const [errors, setErrors] = useState({});

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  function validate() {
    const e = {};
    if (!form.fullName.trim()) e.fullName = 'Full name is required';
    if (!form.email.trim()) e.email = 'Email is required';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) e.email = 'Invalid email format';
    if (!form.password) e.password = 'Password is required';
    else if (form.password.length < 6) e.password = 'Password must be at least 6 characters';
    if (!form.confirmPassword) e.confirmPassword = 'Please confirm your password';
    else if (form.password !== form.confirmPassword) e.confirmPassword = 'Passwords do not match';
    if (!form.phone.trim()) e.phone = 'Phone number is required';
    setErrors(e);
    return Object.keys(e).length === 0;
  }

  async function handleSubmit(e) {
    e.preventDefault();
    if (!validate()) return;
    setLoading(true);
    try {
      const res = await authService.register({
        fullName: form.fullName,
        email: form.email,
        password: form.password,
        phone: form.phone,
        role: form.role,
      });
      toast.success('Account created successfully!');
      navigate('/login');
    } catch (err) {
      toast.error(err?.response?.data?.message || 'Sign up failed');
    } finally {
      setLoading(false);
    }
  }

  return (
    <div style={styles.container}>
      <div style={styles.content}>
        {/* Logo */}
        <div style={styles.logo}>
          <Stethoscope size={40} color="var(--teal)" />
          <h1 style={styles.brandName}>MediBook</h1>
        </div>

        <Card style={styles.card}>
          <div style={styles.header}>
            <Button variant="ghost" onClick={() => navigate(-1)} style={styles.backBtn}>
              <ArrowLeft size={16} />
            </Button>
            <h2 style={styles.title}>Create Account</h2>
          </div>
          <p style={styles.subtitle}>Sign up to get started with MediBook</p>

          <form onSubmit={handleSubmit} style={styles.form}>
            <Input
              label="Full Name"
              type="text"
              placeholder="Enter your full name"
              value={form.fullName}
              onChange={e => set('fullName', e.target.value)}
              error={errors.fullName}
              icon={<User size={18} />}
            />

            <Input
              label="Email"
              type="email"
              placeholder="Enter your email"
              value={form.email}
              onChange={e => set('email', e.target.value)}
              error={errors.email}
              icon={<Mail size={18} />}
            />

            <Input
              label="Phone Number"
              type="tel"
              placeholder="Enter your phone number"
              value={form.phone}
              onChange={e => set('phone', e.target.value)}
              error={errors.phone}
              icon={<Phone size={18} />}
            />

            <div style={styles.field}>
              <label style={styles.label}>Role *</label>
              <select
                value={form.role}
                onChange={e => set('role', e.target.value)}
                style={styles.select}
              >
                <option value="Patient">Patient</option>
                <option value="Provider">Provider</option>
                <option value="Admin">Admin</option>
              </select>
            </div>

            <div style={styles.passwordWrapper}>
              <Input
                label="Password"
                type={showPassword ? 'text' : 'password'}
                placeholder="Create a password"
                value={form.password}
                onChange={e => set('password', e.target.value)}
                error={errors.password}
                icon={<Lock size={18} />}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                style={styles.eyeBtn}
              >
                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>

            <Input
              label="Confirm Password"
              type="password"
              placeholder="Confirm your password"
              value={form.confirmPassword}
              onChange={e => set('confirmPassword', e.target.value)}
              error={errors.confirmPassword}
            />

            <Button
              type="submit"
              variant="dark"
              size="lg"
              disabled={loading}
              style={styles.submitBtn}
            >
              {loading ? 'Creating account...' : 'Sign Up'}
            </Button>
          </form>

          <div style={styles.divider}>
            <span style={styles.dividerText}>or</span>
          </div>

          <div style={styles.signupLink}>
            <span style={styles.signupText}>Already have an account? </span>
            <a href="#" onClick={(e) => { e.preventDefault(); navigate('/login'); }} style={styles.signupAction}>
              Sign in
            </a>
          </div>
        </Card>
      </div>
    </div>
  );
}

const styles = {
  container: {
    minHeight: '100vh',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: 'linear-gradient(135deg, #f5f7fa 0%, #e4e8ec 100%)',
    padding: '20px',
  },
  content: {
    width: '100%',
    maxWidth: 440,
  },
  logo: {
    display: 'flex',
    alignItems: 'center',
    gap: 10,
    marginBottom: 24,
    justifyContent: 'center',
  },
  brandName: {
    fontFamily: 'var(--font-display)',
    fontSize: '1.8rem',
    fontWeight: 700,
    color: 'var(--ink)',
    margin: 0,
  },
  card: {
    padding: '32px 28px',
    boxShadow: '0 20px 60px rgba(0, 0, 0, 0.1)',
  },
  header: {
    display: 'flex',
    alignItems: 'center',
    gap: 12,
    marginBottom: 8,
  },
  backBtn: {
    padding: '8px',
  },
  title: {
    fontFamily: 'var(--font-display)',
    fontSize: '1.5rem',
    fontWeight: 700,
    color: 'var(--ink)',
    margin: 0,
  },
  subtitle: {
    color: 'var(--text-muted)',
    fontSize: '0.9rem',
    marginBottom: 24,
  },
  form: {
    display: 'flex',
    flexDirection: 'column',
    gap: 14,
  },
  passwordWrapper: {
    position: 'relative',
  },
  eyeBtn: {
    position: 'absolute',
    right: 12,
    top: 38,
    background: 'none',
    border: 'none',
    cursor: 'pointer',
    color: 'var(--text-muted)',
    padding: 4,
  },
  field: {
    marginBottom: 4,
  },
  label: {
    display: 'block',
    fontSize: '0.85rem',
    fontWeight: 600,
    color: 'var(--ink)',
    marginBottom: 6,
  },
  select: {
    width: '100%',
    padding: '10px 12px',
    border: '1px solid var(--border)',
    borderRadius: 8,
    fontSize: '0.9rem',
    background: '#fff',
    color: 'var(--ink)',
    cursor: 'pointer',
  },
  submitBtn: {
    marginTop: 8,
  },
  divider: {
    display: 'flex',
    alignItems: 'center',
    margin: '24px 0',
  },
  dividerText: {
    padding: '0 16px',
    color: 'var(--text-muted)',
    fontSize: '0.85rem',
  },
  signupLink: {
    textAlign: 'center',
  },
  signupText: {
    color: 'var(--text-muted)',
    fontSize: '0.9rem',
  },
  signupAction: {
    color: 'var(--teal)',
    textDecoration: 'none',
    fontSize: '0.9rem',
    fontWeight: 600,
    cursor: 'pointer',
  },
};
